import{_ as e,c as i,o as r,a2 as t}from"./chunks/framework.CIiVzG-O.js";const p=JSON.parse('{"title":"プライバシーポリシー","description":"qDiff はデータを収集しません。アプリが Mac 上で読み取る内容と、購入の扱いについて説明します。","frontmatter":{"title":"プライバシーポリシー","description":"qDiff はデータを収集しません。アプリが Mac 上で読み取る内容と、購入の扱いについて説明します。"},"headers":[],"relativePath":"ja/privacy/index.md","filePath":"ja/privacy/index.md","lastUpdated":1794296122000}'),o={name:"ja/privacy/index.md"};function l(n,a,d,h,c,f){return r(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="プライバシーポリシー" tabindex="-1">プライバシーポリシー <a class="header-anchor" href="#プライバシーポリシー" aria-label="Permalink to &quot;プライバシーポリシー&quot;">​</a></h1><p><em>最終更新日: 2026年11月6日</em></p><p><strong>要点をお伝えすると、qDiff は個人データを収集しません。</strong> ローカルで動作する ツールです。ファイルはお使いの Mac 内に留まります。</p><h2 id="qdiff-が読み取るもの" tabindex="-1">qDiff が読み取るもの <a class="header-anchor" href="#qdiff-が読み取るもの" aria-label="Permalink to &quot;qDiff が読み取るもの&quot;">​</a></h2><p>qDiff は、アプリ内で選んだファイルとフォルダだけを開き、比較を表示するために お使いのデバイス上で処理します。フォルダへのアクセスを許可した場合、その 権限は利便性のために保持されますが、「設定」からいつでも取り消せます。 私たちにアップロードされるものは何もありません。</p><h2 id="行わないこと" tabindex="-1">行わないこと <a class="header-anchor" href="#行わないこと" aria-label="Permalink to &quot;行わないこと&quot;">​</a></h2><ul><li>氏名、メールアドレス、利用統計は収集しません。</li><li>アプリやウェブサイトを横断して追跡しません。</li><li>アカウントやサインインを要求しません。</li><li>広告の表示、解析やサードパーティによる追跡の組み込みは行いません。</li><li>ファイルをサーバーへ同期・バックアップしません。</li></ul><h2 id="ネットワークアクセス" tabindex="-1">ネットワークアクセス <a class="header-anchor" href="#ネットワークアクセス" aria-label="Permalink to &quot;ネットワークアクセス&quot;">​</a></h2><p>qDiff はオフラインで動作します。唯一任意で行われるネットワーク通信は、 アプリ内の「その他のアプリ」ページで公開アプリ一覧を読み込むときだけです。 この通信には、あなた、ファイル、デバイスに関する情報は一切含まれず、 利用データが送信されることもありません。</p><h2 id="購入" tabindex="-1">購入 <a class="header-anchor" href="#購入" aria-label="Permalink to &quot;購入&quot;">​</a></h2><p>任意の一度きりの購入は、Mac App Store とお使いの Apple ID によって完全に 処理されます。私たちが支払い情報を目にすることはありません。購入はアプリ内の 「設定」から復元できます。</p><h2 id="このウェブサイトについて" tabindex="-1">このウェブサイトについて <a class="header-anchor" href="#このウェブサイトについて" aria-label="Permalink to &quot;このウェブサイトについて&quot;">​</a></h2><p>このサイトは静的なページの集まりです。ログイン、解析、広告用 Cookie は ありません。ページを開くだけで、何かをご提供いただく必要は生じません。</p><h2 id="子どもについて" tabindex="-1">子どもについて <a class="header-anchor" href="#子どもについて" aria-label="Permalink to &quot;子どもについて&quot;">​</a></h2><p>qDiff は子どもを対象としておらず、故意に情報を収集することはありません。</p><h2 id="変更について" tabindex="-1">変更について <a class="header-anchor" href="#変更について" aria-label="Permalink to &quot;変更について&quot;">​</a></h2><p>本ポリシーを変更する場合は、このページと上記の日付を更新します。アプリが 読み取る内容に影響する変更は、アプリ本体でもお知らせします。</p><h2 id="お問い合わせ" tabindex="-1">お問い合わせ <a class="header-anchor" href="#お問い合わせ" aria-label="Permalink to &quot;お問い合わせ&quot;">​</a></h2><p>プライバシーについてご質問は、 <a href="mailto:qdiff@w3cub.com" target="_blank" rel="noreferrer">qdiff@w3cub.com</a>までご連絡ください。</p>',19)])])}const q=e(o,[["render",l]]);export{p as __pageData,q as default};
